import { CheckCircle2, Loader2 } from "lucide-react";
import { getLocale, getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import { getCheckoutSession } from "@intelligo-dev/billing";

import { Link, redirect } from "@/i18n/navigation";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

interface CheckoutSuccessPageProps {
  searchParams: Promise<{ session_id?: string }>;
}

/**
 * Checkout success page.
 *
 * Verifies the session by querying Stripe directly through
 * `getCheckoutSession` (`@intelligo-dev/billing`) rather than trusting the
 * workspace's local subscription row. Stripe's webhook can arrive
 * 15-20% slower than the browser's redirect to this page; reading the
 * checkout session itself is what makes this page show the right plan
 * immediately regardless of webhook timing. No Stripe call happens in
 * this component — that's the whole point of routing through the
 * service instead of `getStripe()` directly.
 */
export default async function CheckoutSuccessPage({
  searchParams,
}: CheckoutSuccessPageProps) {
  const t = await getTranslations("checkout");
  const { session_id: sessionId } = await searchParams;

  if (!sessionId) {
    redirect({ href: "/pricing", locale: await getLocale() });
    return null; // redirect throws; this narrows sessionId for TS
  }

  await requireWorkspace();

  try {
    const session = await getCheckoutSession({ sessionId });

    if (session.status === "complete" && session.isSubscriptionActive) {
      return (
        <div className="container max-w-2xl py-16">
          <Card className="border-green-200 bg-green-50/50 dark:border-green-900 dark:bg-green-950/30">
            <CardHeader className="text-center">
              <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-green-100 dark:bg-green-900">
                <CheckCircle2 className="h-10 w-10 text-green-600 dark:text-green-400" />
              </div>
              <CardTitle className="text-3xl">{t("success.title")}</CardTitle>
              <CardDescription className="text-base">
                {session.planName
                  ? t("success.planActive", { planName: session.planName })
                  : t("success.subscriptionActive")}
              </CardDescription>
            </CardHeader>

            <CardContent className="space-y-6">
              <div className="rounded-lg border bg-background p-4">
                <div className="flex items-center justify-between">
                  <div>
                    {session.planName && (
                      <p className="font-medium">
                        {t("success.planLabel", { planName: session.planName })}
                      </p>
                    )}
                    {session.billingInterval && (
                      <p className="text-sm text-muted-foreground">
                        {session.billingInterval === "month"
                          ? t("success.billedMonthly")
                          : t("success.billedYearly")}
                      </p>
                    )}
                  </div>
                  <Badge variant="default" className="bg-green-600">
                    {t("success.status")}
                  </Badge>
                </div>
              </div>

              {session.customerEmail && (
                <p className="text-center text-sm text-muted-foreground">
                  {t("success.receiptSent", { email: session.customerEmail })}
                </p>
              )}
            </CardContent>

            <CardFooter className="flex flex-col gap-3 sm:flex-row">
              <Button asChild className="w-full sm:flex-1">
                <Link href="/dashboard">{t("actions.goToDashboard")}</Link>
              </Button>
              <Button asChild variant="outline" className="w-full sm:flex-1">
                <Link href="/settings/billing">
                  {t("actions.viewBillingSettings")}
                </Link>
              </Button>
            </CardFooter>
          </Card>
        </div>
      );
    }

    if (session.status !== "complete") {
      return (
        <div className="container max-w-2xl py-16">
          <Card>
            <CardHeader className="text-center">
              <CardTitle>{t("pending.title")}</CardTitle>
              <CardDescription>{t("pending.description")}</CardDescription>
            </CardHeader>
            <CardContent className="flex justify-center">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </CardContent>
            <CardFooter className="justify-center">
              <Button asChild variant="outline">
                <Link href="/settings/billing">
                  {t("actions.checkBillingSettings")}
                </Link>
              </Button>
            </CardFooter>
          </Card>
        </div>
      );
    }

    return (
      <div className="container max-w-2xl py-16">
        <Card>
          <CardHeader className="text-center">
            <CardTitle>{t("received.title")}</CardTitle>
            <CardDescription>{t("received.description")}</CardDescription>
          </CardHeader>
          <CardFooter className="justify-center gap-3">
            <Button asChild>
              <Link href="/dashboard">{t("actions.goToDashboard")}</Link>
            </Button>
            <Button asChild variant="outline">
              <Link href="/settings/billing">
                {t("actions.viewBillingSettings")}
              </Link>
            </Button>
          </CardFooter>
        </Card>
      </div>
    );
  } catch {
    // session_not_found (a stale/invalid session id) or a Stripe
    // outage — either way, the customer likely did pay. Show a
    // generic thank-you and point at billing settings rather than
    // surfacing a Stripe error to someone who just completed checkout.
    return (
      <div className="container max-w-2xl py-16">
        <Card>
          <CardHeader className="text-center">
            <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-green-100 dark:bg-green-900">
              <CheckCircle2 className="h-10 w-10 text-green-600 dark:text-green-400" />
            </div>
            <CardTitle>{t("fallback.title")}</CardTitle>
            <CardDescription>{t("fallback.description")}</CardDescription>
          </CardHeader>
          <CardContent className="text-center">
            <p className="text-sm text-muted-foreground">
              {t("fallback.note")}
            </p>
          </CardContent>
          <CardFooter className="justify-center gap-3">
            <Button asChild>
              <Link href="/dashboard">{t("actions.goToDashboard")}</Link>
            </Button>
            <Button asChild variant="outline">
              <Link href="/settings/billing">
                {t("actions.viewBillingSettings")}
              </Link>
            </Button>
          </CardFooter>
        </Card>
      </div>
    );
  }
}

"use client";

/**
 * Client error boundary for the checkout success route. Self-contained
 * per the repo-wide registry standard: no shared app-internal error
 * component, no error-reporting SDK.
 */

import { useEffect } from "react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

export default function CheckoutSuccessError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const t = useTranslations("checkout");

  useEffect(() => {
    console.error("[checkout/success] error boundary caught:", error);
  }, [error]);

  return (
    <div className="flex min-h-[60vh] items-center justify-center p-4">
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertDescription>{t("error.description")}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("actions.tryAgain")}</Button>
          <Button asChild variant="outline">
            <Link href="/settings/billing">
              {t("actions.viewBillingSettings")}
            </Link>
          </Button>
        </div>
      </div>
    </div>
  );
}

{
  "actions": {
    "tryAgain": "Try again",
    "goToDashboard": "Go to dashboard",
    "viewBillingSettings": "View billing settings",
    "checkBillingSettings": "Check billing settings"
  },
  "error": {
    "description": "Something went wrong while confirming your payment. If you were charged, it will still be applied — check your billing settings."
  },
  "success": {
    "title": "You're all set",
    "subscriptionActive": "Your subscription is active.",
    "planActive": "You're now on the {planName} plan.",
    "planLabel": "{planName} plan",
    "billedMonthly": "Billed monthly",
    "billedYearly": "Billed yearly",
    "status": "Active",
    "receiptSent": "A receipt was sent to {email}."
  },
  "pending": {
    "title": "Finishing up",
    "description": "We're confirming your payment. This usually takes a few seconds."
  },
  "received": {
    "title": "Payment received",
    "description": "Your payment went through. It may take a moment to reflect in your billing settings."
  },
  "fallback": {
    "title": "Thank you",
    "description": "Your payment is being processed.",
    "note": "Check your billing settings for the latest status."
  }
}
